base = Path('/app/data')
sub = Path('/app/submissions/solution.csv')

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

config = json.load(open(base/'config.json'))
T = int(config['planning_horizon_slots'])
locked = int(config['locked_nonanticipative_slots'])
tol = float(config['feasibility_tolerance'])

basins = {r['basin_id']: r for r in read_csv(base/'basins.csv')}
controls = {r['control_id']: r for r in read_csv(base/'controls.csv')}
scenarios = {r['scenario_id']: r for r in read_csv(base/'scenarios.csv')}
control_groups = {r['group_id']: r for r in read_csv(base/'control_groups.csv')}

a_by_sc_ctl_slot = {}
for r in read_csv(base/'control_availability.csv'):
    a_by_sc_ctl_slot[(r['scenario_id'], r['control_id'], int(r['slot']))] = float(r['capacity_multiplier'])

treat_cap = {}
for r in read_csv(base/'treatment_capacity.csv'):
    treat_cap[(r['scenario_id'], int(r['slot']))] = float(r['max_treatment_ml'])

outfall_cap = {}
for r in read_csv(base/'outfall_limits.csv'):
    outfall_cap[(r['scenario_id'], r['outfall_id'], int(r['slot']))] = float(r['max_release_ml'])

inflow = {}
for r in read_csv(base/'scenario_inflows.csv'):
    inflow[(r['scenario_id'], r['basin_id'], int(r['slot']))] = float(r['inflow_ml'])

group_duty = defaultdict(list)
for r in read_csv(base/'group_duty_limits.csv'):
    group_duty[r['group_id']].append((int(r['window_slots']), float(r['max_volume_ml'])))

# parse solution exact rows
raw_rows = []
with open(sub, newline='') as f:
    reader = csv.DictReader(f)
    header = reader.fieldnames
    for i,row in enumerate(reader, start=2):
        raw_rows.append((i,row))

violations = defaultdict(list)

expected_header = ['scenario_id','slot','control_id','volume_ml']
if header "'!= expected_header:
    violations['"'schema'].append({'row':'header','msg':f'header {header} "'!= {expected_header}'"'})

agg = defaultdict(float)
key_rows = defaultdict(list)
for line,row in raw_rows:
    # nullability
    for c in expected_header:
        if row.get(c) is None or row[c] == '':
            violations['schema'].append({'row':line,'key':tuple(row.get(k,'') for k in expected_header),'msg':f'null/empty {c}'})
    key = (row['scenario_id'], row['slot'], row['control_id'])
    key_rows[key].append(line)
    try:
        vol = float(row['volume_ml'])
    except Exception:
        violations['schema'].append({'row':line,'key':key,'msg':'non-numeric volume'})
        continue
    agg[(row['scenario_id'], int(row['slot']) if row['slot'].isdigit() or (row['slot'].startswith('-') and row['slot'][1:].isdigit()) else row['slot'], row['control_id'])] += vol

for key, lines in key_rows.items():
    if len(lines) > 1:
        violations['schema'].append({'row':lines,'key':key,'msg':'duplicate key rows'})

# identifier domains and nonneg slot range/volume positive
valid_scen = set(scenarios)
valid_ctl = set(controls)
for line,row in raw_rows:
    sid=row['scenario_id']; cid=row['control_id']; slot_str=row['slot']
    try:
        slot=int(slot_str)
    except Exception:
        violations['id'].append({'row':line,'key':(sid,slot_str,cid),'msg':'slot not integer','observed':slot_str})
        continue
    try:
        vol=float(row['volume_ml'])
    except Exception:
        continue
    if sid not in valid_scen:
        violations['id'].append({'row':line,'key':(sid,slot,cid),'msg':'invalid scenario'})
    if cid not in valid_ctl:
        violations['id'].append({'row':line,'key':(sid,slot,cid),'msg':'invalid control'})
    if not (0 <= slot < T):
        violations['id'].append({'row':line,'key':(sid,slot,cid),'msg':'slot out of range','observed':slot,'required':f'[0,{T-1}]'})
    if vol <= 0 + tol:
        violations['id'].append({'row':line,'key':(sid,slot,cid),'msg':'nonpositive exported volume','observed':vol,'required':f'>{tol}'})

# build dense matrix
sol = defaultdict(float)
for (sid,slot,cid), vol in agg.items():
    if isinstance(slot,int):
        sol[(sid,slot,cid)] += vol

# locked prefix exact equality across scenarios
scenario_list = sorted(scenarios)
control_list = sorted(controls)
for slot in range(locked):
    base_sid = scenario_list[0]
    for cid in control_list:
        base_v = sol[(base_sid,slot,cid)]
        for sid in scenario_list[1:]:
            v = sol[(sid,slot,cid)]
            if abs(v-base_v) > tol:
                violations['nonanticipative'].append({'key':(sid,slot,cid),'reference_scenario':base_sid,'observed':v,'required':base_v})

# control and group properties
outfall_controls = defaultdict(list)
wwtp_controls = []
group_controls = defaultdict(list)
for cid,r in controls.items():
    group_controls[r['group_id']].append(cid)
    if r['to_node'] == 'WWTP':
        wwtp_controls.append(cid)
    if r['to_node'].startswith('O_'):
        outfall_controls[r['to_node']].append(cid)

# per-scenario slot checks, starts, activity, group etc.
control_starts = defaultdict(int)
group_starts = defaultdict(int)

for sid in scenario_list:
    prev_v = {cid:0.0 for cid in control_list}
    prev_active = {cid:False for cid in control_list}
    for slot in range(T):
        # control level
        for cid,r in controls.items():
            v = sol[(sid,slot,cid)]
            max_cap = float(r['max_volume_ml']) * a_by_sc_ctl_slot[(sid,cid,slot)]
            min_pos = float(r['min_positive_volume_ml'])
            ramp = float(r['ramp_volume_ml'])
            if v > max_cap + tol:
                violations['capacity'].append({'key':(sid,slot,cid),'rule':'control availability capacity','observed':v,'required':f'<= {max_cap}'})
            if v > tol and v + tol < min_pos:
                violations['setup'].append({'key':(sid,slot,cid),'rule':'minimum positive volume','observed':v,'required':f'>= {min_pos}'})
            if abs(v - prev_v[cid]) > ramp + tol:
                violations['ramps'].append({'key':(sid,slot,cid),'rule':'ramp limit','observed':abs(v-prev_v[cid]),'required':f'<= {ramp}','prev':prev_v[cid],'curr':v})
            active = v > tol
            if active and not prev_active[cid]:
                control_starts[(sid,cid)] += 1
                group_starts[(sid,r['group_id'])] += 1
            prev_v[cid] = v
            prev_active[cid] = active
        # group active limits
        for gid, g in control_groups.items():
            active_ct = sum(sol[(sid,slot,cid)] > tol for cid in group_controls[gid])
            lim = int(g['max_active_controls_per_slot'])
            if active_ct > lim:
                violations['nonoverlap'].append({'key':(sid,slot,gid),'rule':'max active controls per slot','observed':active_ct,'required':f'<= {lim}','active_controls':[cid for cid in group_controls[gid] if sol[(sid,slot,cid)] > tol]})
        # treatment capacity
        tot_ww = sum(sol[(sid,slot,cid)] for cid in wwtp_controls)
        lim = treat_cap[(sid,slot)]
        if tot_ww > lim + tol:
            violations['capacity'].append({'key':(sid,slot,'WWTP'),'rule':'treatment capacity','observed':tot_ww,'required':f'<= {lim}'})
        # outfalls
        for oid, cids in outfall_controls.items():
            tot = sum(sol[(sid,slot,cid)] for cid in cids)
            lim = outfall_cap[(sid,oid,slot)]
            if tot > lim + tol:
                violations['capacity'].append({'key':(sid,slot,oid),'rule':'outfall capacity','observed':tot,'required':f'<= {lim}'})
    # starts limits after horizon scan
    for cid,r in controls.items():
        n = control_starts[(sid,cid)]
        lim = int(r['max_starts'])
        if n > lim:
            violations['setup'].append({'key':(sid,cid),'rule':'control max starts per scenario','observed':n,'required':f'<= {lim}'})
    for gid,g in control_groups.items():
        n = group_starts[(sid,gid)]
        lim = int(g['max_group_starts_per_scenario'])
        if n > lim:
            violations['setup'].append({'key':(sid,gid),'rule':'group max starts per scenario','observed':n,'required':f'<= {lim}'})
    # duty limits
    for gid, defs in group_duty.items():
        cids = group_controls[gid]
        series = [sum(sol[(sid,t,cid)] for cid in cids) for t in range(T)]
        for win, lim in defs:
            for start in range(T-win+1):
                total = sum(series[start:start+win])
                if total > lim + tol:
                    violations['capacity'].append({'key':(sid,f'{start}-{start+win-1}',gid),'rule':'rolling duty volume','observed':total,'required':f'<= {lim}'})

# travel horizon and dynamics
# precompute arrivals indexed by arrival slot from source actions
for sid in scenario_list:
    arrivals = defaultdict(float)  # (slot, basin)
    # first detect illegal post-horizon arrivals
    for cid,r in controls.items():
        delay = int(r['travel_delay_slots'])
        dest = r['to_node']
        for slot in range(T):
            v = sol[(sid,slot,cid)]
            if v <= tol:
                continue
            if dest in basins:
                arr = slot + delay
                if arr >= T:
                    violations['time'].append({'key':(sid,slot,cid),'rule':'arrival within horizon','observed':arr,'required':f'<= {T-1}'})
                else:
                    arrivals[(arr,dest)] += v
    stor_prev = {b: float(r['initial_storage_ml']) for b,r in basins.items()}
    overflow_total = defaultdict(float)
    final_stor = {}
    for slot in range(T):
        available = {}
        for b in basins:
            available[b] = stor_prev[b] + inflow[(sid,b,slot)] + arrivals[(slot,b)]
        # conservation source availability by basin
        outflow_by_b = defaultdict(float)
        for cid,r in controls.items():
            outflow_by_b[r['from_basin']] += sol[(sid,slot,cid)]
        for b, out in outflow_by_b.items():
            if out > available[b] + tol:
                violations['conservation'].append({'key':(sid,slot,b),'rule':'source basin availability','observed':out,'required':f'<= {available[b]}','available':available[b]})
        stor_next = {}
        for b, rb in basins.items():
            pre = available[b] - outflow_by_b[b]
            cap = float(rb['capacity_ml'])
            overflow = max(0.0, pre - cap)
            overflow_total[b] += overflow
            stor_next[b] = min(cap, pre)
            # negative storage if outflow > available already captured; record exact final if negative beyond tol
            if stor_next[b] < -tol:
                violations['conservation'].append({'key':(sid,slot,b),'rule':'nonnegative storage','observed':stor_next[b],'required':'>= 0'})
        stor_prev = stor_next
    final_stor = stor_prev

# objective components we can recompute exactly enough? let's compute identifiable scenario costs using apparent public formula.
energy_price = {int(r['slot']): float(r['price_per_kwh']) for r in read_csv(base/'energy_tariffs.csv')}
district_data = {r['district']: r for r in read_csv(base/'district_service.csv')}
first_flush_slots = int(config['first_flush_slots'])
final_pen = float(config['final_storage_penalty_per_ml'])
first_flush_pen = float(config['first_flush_release_penalty_per_ml'])
district_pen = float(config['district_overflow_penalty_per_ml'])

# recompute scenario state and costs
sc_cost = {}
district_expected_overflow = defaultdict(float)
scenario_overflow_by_district = defaultdict(float)
for sid,sr in scenarios.items():
    prob = float(sr['probability'])
    arrivals = defaultdict(float)
    for cid,r in controls.items():
        delay = int(r['travel_delay_slots'])
        dest = r['to_node']
        for slot in range(T):
            v = sol[(sid,slot,cid)]
            if v <= tol:
                continue
            if dest in basins and slot+delay < T:
                arrivals[(slot+delay,dest)] += v
    stor_prev = {b: float(r['initial_storage_ml']) for b,r in basins.items()}
    overflow_basin = defaultdict(float)
    cost = 0.0
    for slot in range(T):
        available = {b: stor_prev[b] + inflow[(sid,b,slot)] + arrivals[(slot,b)] for b in basins}
        out_b = defaultdict(float)
        for cid,r in controls.items():
            v = sol[(sid,slot,cid)]
            out_b[r['from_basin']] += v
            if v > tol:
                cost += v * float(r['movement_cost_per_ml'])
                cost += v * float(r['energy_kwh_per_ml']) * energy_price[slot]
                if slot < first_flush_slots and r['first_flush_sensitive'] == '1' and r['to_node'].startswith('O_'):
                    cost += v * first_flush_pen
        for cid,r in controls.items():
            v=sol[(sid,slot,cid)]
            prev= sol[(sid,slot-1,cid)] if slot>0 else 0.0
            if v>tol and prev<=tol:
                cost += float(r['start_cost'])
        stor_next = {}
        for b,rb in basins.items():
            pre = available[b] - out_b[b]
            cap = float(rb['capacity_ml'])
            overflow = max(0.0, pre-cap)
            overflow_basin[b] += overflow
            if overflow>0:
                cost += overflow * float(rb['flood_damage_cost_per_ml'])
                if rb['critical_asset']=='1':
                    cost += overflow * float(rb['flood_damage_cost_per_ml'])
                if rb['combined_sewer']=='1':
                    cost += overflow * float(rb['pollution_cost_per_ml'])
            stor_next[b] = min(cap, pre)
        stor_prev = stor_next
    for b,rb in basins.items():
        excess = max(0.0, stor_prev[b] - float(rb['target_final_storage_ml']))
        cost += excess * final_pen
        d = rb['district']
        scenario_overflow_by_district[(sid,d)] += overflow_basin[b]
    sc_cost[sid] = cost
    for d in district_data:
        district_expected_overflow[d] += prob * scenario_overflow_by_district[(sid,d)]
# ambiguous district formula candidate
for d, dr in district_data.items():
    excess = max(0.0, district_expected_overflow[d] - float(dr['expected_overflow_target_ml']))
    # assume multiplier scales penalty
    mult = float(dr['critical_multiplier'])
    for sid in scenarios:
        pass
# produce summary
print('Violation families/counts:')
for fam, items in violations.items():
    print(fam, len(items))
print('\\nFirst few violations per family:')
for fam, items in violations.items():
    print('\\n##',fam)
    for item in items[:10]:
        print(item)
print('\\nScenario costs identifiable (excluding ambiguous district/CVaR treatment):')
for sid,c in sc_cost.items():
    print(sid, round(c,3))
print('Expected overflow by district:')
for d,v in district_expected_overflow.items():
    print(d, round(v,3), 'target', district_data[d]['expected_overflow_target_ml'], 'mult', district_data[d]['critical_multiplier'])
